// CreateNewProject.js
import React, { useEffect, useState, useContext } from "react";
import { useCallback } from "react";
import axios from "axios";
import { Table, Button } from "react-bootstrap";
import { useNavigate } from "react-router-dom";
import {
    Search,
    Plus,
    Download,
    Upload
} from "react-bootstrap-icons";
import { ClipboardList } from "lucide-react";
import "bootstrap/dist/css/bootstrap.min.css";
import "../css/Table.css"
import SearchInputFields from "../components/SearchInputFields"
import Pager from "../components/Pager";
import { useOutletContext } from "react-router-dom";
import LoadingSpinner from "../components/LoadingSpinner";
import "../css/ModuleDashboard.css"
import { OverlayTrigger, Tooltip } from "react-bootstrap";
import { TrainingContext } from "./TrainingContext";
import { FaEdit, FaSearch, FaTrash } from "react-icons/fa";
const BASE_URL = process.env.REACT_APP_BASE_URL;



const ProductionCompoundMaster = () => {
    const {
        setUploadUrl
    } = useContext(TrainingContext);
    const [loading, setLoading] = useState(true);
    const [tableData, setTableData] = useState([]);
    const [formData, setFormData] = useState({
        compound: "",
        masterBatch: ""
    });
    const [currentPage, setCurrentPage] = useState(0);
    const [totalPages, setTotalPages] = useState(0);
    const [pageSize, setPageSize] = useState(10);// dynamic in real apps
    const sequenceNumber = pageSize * currentPage;
    const navigate = useNavigate();
    const { setAlert, setStaticAlert, setReloadFunction } = useOutletContext();

    const handleChange = (e) => {
        const { name, value } = e.target;
        const keys = name.split(".");

        setFormData(prev => {
            const updated = { ...prev };
            let current = updated;

            keys.forEach((key, index) => {
                if (index === keys.length - 1) {
                    current[key] = value;
                } else {
                    current[key] = { ...current[key] };
                    current = current[key];
                }
            });

            return updated;
        });
    };




    const loadTableData = useCallback(async () => {
        try {
            console.log(formData);
            setLoading(true);

            const response = await axios.post(
                BASE_URL + "/WebApplication/Controllers/getProductionCompound/" + currentPage + "/" + pageSize,
                formData,
                { withCredentials: true }
            );

            console.log("Data Load Successfully:", response);

            setTableData(response.data.content);
            setTotalPages(response.data.totalPages);
            setCurrentPage(response.data.pageable.pageNumber);

        } catch (error) {
            console.log(error);
        } finally {
            setLoading(false);
        }

    }, [formData, currentPage, pageSize]);

    useEffect(() => {
        if (setReloadFunction) {
            setReloadFunction(() => loadTableData);
        }
    }, []);

    // Handle form change
    const deleteData = async (id) => {
        try {
            const response = await axios.delete(
                `${BASE_URL}/WebApplication/Controllers/deleteProductionCompound/${id}`,
                { withCredentials: true }
            );

            setAlert({ type: "success", message: "Success : " + response.data });
            loadTableData();
        } catch (error) {
            setAlert({ type: "danger", message: "Error : " + error.response.data });
            console.error(error);
            loadTableData();
        }
    };

    useEffect(() => {
        loadTableData();
    }, [currentPage, pageSize]); // empty deps → runs once

    const handleEnterKey = (e, callback) => {
        if (e.key === "Enter") {
            e.preventDefault();
            callback();
        }
    };

    const downloadTemplate = async () => {
        try {

            setLoading(true);

            const response = await axios.get(
                BASE_URL + "/WebApplication/Controllers/download/template/productionCompound",
                {
                    responseType: "blob", // ✅ VERY IMPORTANT
                    withCredentials: true,
                }
            );

            // Create blob link
            const url = window.URL.createObjectURL(new Blob([response.data]));

            const link = document.createElement("a");
            link.href = url;
            link.setAttribute("download", "compound_Master_Template.xlsx");
            document.body.appendChild(link);
            link.click();

            // Cleanup
            link.remove();
            window.URL.revokeObjectURL(url);

            setLoading(false);

        } catch (error) {
            console.error("Download error:", error);

            setLoading(false);
        }
    };


    const downloadData = async () => {
        try {

            setLoading(true);

            const response = await axios.post(
                BASE_URL + "/WebApplication/Controllers/download/data/productionCompound",
                formData,
                {
                    responseType: "blob", // ✅ VERY IMPORTANT
                    withCredentials: true,
                }
            );

            // Create blob link
            const url = window.URL.createObjectURL(new Blob([response.data]));

            const link = document.createElement("a");
            link.href = url;
            link.setAttribute("download", "compound_Master.xlsx");
            document.body.appendChild(link);
            link.click();

            // Cleanup
            link.remove();
            window.URL.revokeObjectURL(url);

            setLoading(false);

        } catch (error) {
            console.error("Download error:", error);

            setLoading(false);
        }
    };

    // Resource mode
    const showUploadModal = async (resources) => {
        setStaticAlert({ type: "success", message: "Resource Download : " });
        setUploadUrl("uploadProductionCompound");

    };


    const updateCheckbox = async (id, field, value) => {
    try {
        const payload = {
            productionCompoundId: id,
            [field]: value ? "1" : "0"
        };

        await axios.post(
            BASE_URL + "/WebApplication/Controllers/updateCompoundCheckbox",
            payload,
            { withCredentials: true }
        );

        // Update UI instantly (no reload)
        setTableData(prev =>
            prev.map(item =>
                item.productionCompoundId === id
                    ? { ...item, [field]: value ? "1" : "0" }
                    : item
            )
        );

    } catch (error) {
        console.error("Checkbox update failed", error);
        setAlert({ type: "danger", message: "Update failed" });
    }
};

    return (
        <div className="card shadow-lg rounded-0 border-0 bg-light d-flex flex-column p-2"
            style={{
                width: "100%",
                minHeight: "100vh",
                background: "#f4f6f8",
            }}>
            {/* Header */}
            <div className="px-4 py-2"
                style={{
                    background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                    color: "white"
                }}>
                {/* Title */}
                <h4 className="text-end fw-bold mb-0"><ClipboardList size={30} viewBox="0 1 24 24" className="me-2 text-white" />
                    Production Compound Master</h4>
            </div>

            <div className="row g-4 px-1">
                {/* Left Side - Form */}
                <div className="col-md-12">
                    <div className="d-flex my-1" style={{ height: "80vh" }}>
                        {/* LEFT SIDE TABLE */}
                        <div style={{ flex: 1, overflowY: "auto" }}>

                            {loading ? (
                                <LoadingSpinner message={`Loading .....`} />
                            ) : (
                                <Table
                                    bordered
                                    hover
                                    responsive
                                    className="align-middle shadow-sm rounded custom-table responsive-table"
                                // className="table align-middle table-hover mb-0"
                                >
                                    <thead className="bg-light sticky-top">
                                        <tr>
                                            <th colSpan={3}>
                                                <div className="input-group w-100">
                                                    <Button
                                                        className="btn btn-success btn-woco"
                                                        onClick={loadTableData}
                                                    >
                                                        <FaSearch className="me-1" />
                                                    </Button>
                                                    <div className="flex-grow-1">
                                                        <SearchInputFields type="text" placeholder="Compound" name="compound" onChange={(e) => handleChange(e)} value={formData?.compound} onKeyDown={(e) => handleEnterKey(e, loadTableData)} />                                                    </div>
                                                </div>
                                            </th>
                                            <th><SearchInputFields type="text" placeholder="Master Batch" name="masterBatch" onChange={(e) => handleChange(e)} value={formData?.masterBatch} onKeyDown={(e) => handleEnterKey(e, loadTableData)} /></th>
                                          

                                        </tr>
                                    </thead>

                                    <thead style={{ backgroundColor: "#0f6b5b", color: "#fff" }}>
                                        <tr>
                                               <th>Edit / Delete</th>
        <th>S.No</th>
        <th>Compound</th>
        <th>Master Batch</th>
        <th>Formula No</th>
        <th>Batch Weight</th>
        <th>Expiry</th>
        <th>Batch Cutting</th>
        <th>RMS Weight</th>
        <th>Created By</th>
        <th>Date Time</th>
        <th>Image</th>
                                        </tr>
                                    </thead>

                                    <tbody>
{Array.isArray(tableData) && tableData.length > 0 ? (
    tableData.map((object, i) => (
        <tr key={object.productionCompoundId} className="table-row-hover">

            {/* Edit/Delete */}
            <td>
                <div className="d-flex justify-content-center">
                    <Button
                        size="sm"
                        className="me-2 btn-edit"
                        onClick={() =>
                            navigate("/WebApplication/masterDashboard/productionCompoundMaster/addNewProductionCompound", {
                                state: { object },
                            })
                        }
                    >
                        <FaEdit />
                    </Button>

                    <Button
                        size="sm"
                        className="btn-delete"
                        onClick={() => deleteData(object.productionCompoundId)}
                    >
                        <FaTrash />
                    </Button>
                </div>
            </td>

            <td>{sequenceNumber + i + 1}</td>

            <td>{object?.compound}</td>
            <td>{object?.masterBatch}</td>
            <td>{object?.formulaNo}</td>
            <td>{object?.batchWeight}</td>
            <td>{object?.expiry}</td>

            {/* ✅ Batch Cutting Checkbox */}
            <td className="text-center">
                <input
                    type="checkbox"
                    checked={object?.batchCutting === "1"}
                    onChange={(e) =>
                        updateCheckbox(
                            object.productionCompoundId,
                            "batchCutting",
                            e.target.checked
                        )
                    }
                />
            </td>

            {/* ✅ RMS Weight Checkbox */}
            <td className="text-center">
                <input
                    type="checkbox"
                    checked={object?.rmsWeight === "1"}
                    onChange={(e) =>
                        updateCheckbox(
                            object.productionCompoundId,
                            "rmsWeight",
                            e.target.checked
                        )
                    }
                />
            </td>

            <td>{object.createdBy}</td>
            <td>{object.dateTimeModified}</td>

            <td>
                {object.image ? (
                    <a href={object.image} target="_blank" rel="noopener noreferrer">
                        View Image
                    </a>
                ) : (
                    "No Image"
                )}
            </td>

        </tr>
    ))
) : (
    <tr>
        <td colSpan="12" className="text-center">
            No Data Available
        </td>
    </tr>
)}
</tbody>
                                </Table>
                            )}
                        </div>

                        {/* RIGHT SIDE ACTION PANEL */}
                        <div
                            style={{
                                width: "50px",
                                background: "linear-gradient(360deg, #0f6b5b, #0b4f43)",
                                color: "white",
                                borderLeft: "2px solid #e5e7eb",
                                display: "flex",
                                flexDirection: "column",
                                alignItems: "center",
                                paddingTop: "10px",
                                gap: "10px"
                            }}
                        >
                            <OverlayTrigger
                                placement="bottom"
                                overlay={<Tooltip id="download-tooltip">Add</Tooltip>}
                            >
                                <Button
                                    size="sm"
                                    className="btn btn-light shadow-sm"
                                    onClick={() =>
                                        navigate("/WebApplication/masterDashboard/productionCompoundMaster/addNewProductionCompound", { state: { formData } })
                                    }
                                >
                                    <Plus size={20} />
                                </Button>
                            </OverlayTrigger>


                            <OverlayTrigger
                                placement="bottom"
                                overlay={<Tooltip id="download-tooltip">Download Template</Tooltip>}
                            >
                                <Button
                                    size="sm"
                                    className="btn btn-light shadow-sm"
                                    onClick={() => downloadTemplate()}
                                >
                                    <Download size={20} />
                                </Button>
                            </OverlayTrigger>


                            <OverlayTrigger
                                placement="bottom"
                                overlay={<Tooltip id="download-tooltip">Upload Template</Tooltip>}
                            >
                                <Button
                                    size="sm"
                                    className="btn btn-light shadow-sm"
                                    onClick={() => showUploadModal()}
                                >
                                    <Upload size={20} />
                                </Button>
                            </OverlayTrigger>

                            <OverlayTrigger
                                placement="bottom"
                                overlay={<Tooltip id="download-tooltip">Download Data</Tooltip>}
                            >
                                <Button
                                    size="sm"
                                    className="btn btn-light shadow-sm"
                                    onClick={() => downloadData()}
                                >
                                    <Download size={20} />
                                </Button>
                            </OverlayTrigger>

                            {/* Future Buttons */}
                            {/* Download Template */}
                            {/* Upload Template */}

                        </div>

                    </div>
                </div>
            </div>


            <div className="row mt-2 mt-auto m-1"
                style={{
                    background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                    color: "white"
                }}>
                <div className="col-md-6 col-md-12 align-items-center radius-2">
                    <div className="m-2">
                        <Pager
                            currentPage={currentPage}
                            totalPages={totalPages}
                            onPageChange={setCurrentPage}
                            pageSize={pageSize}
                            onPageSizeChange={setPageSize}
                        />
                    </div>

                </div>
            </div>

        </div >
    );
};

export default ProductionCompoundMaster;
