import React from "react";
import woco from "../images/woco.png";
import axios from "axios";
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    BarElement,
    PointElement,
    LineElement,
    ArcElement,
    Tooltip,
    Legend,
} from "chart.js";
import { Button } from "react-bootstrap";
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap/dist/js/bootstrap.bundle.min.js';
import 'bootstrap-icons/font/bootstrap-icons.css';
import "../css/ModuleDashboard.css"
import { useNavigate } from "react-router-dom";

ChartJS.register(
    CategoryScale,
    LinearScale,
    BarElement,
    PointElement,
    LineElement,
    ArcElement,
    Tooltip,
    Legend
);
const BASE_URL = process.env.REACT_APP_BASE_URL;

const ModuleDashboard = () => {

    const navigate = useNavigate();
    const handleLogout = async () => {
        try {
            await axios.post(
                BASE_URL + "/WebApplication/auth/logout",
                { withCredentials: true }
            );
            console.log("Logout Successful:");
            // Redirect to dashboard
            window.location.replace("/WebApplication/loginpage");
        } catch (err) {
            alert("message : Logout failed! Try again."); // 🔔 Show error globally
        }
    };


    //     // Handle form change
    // const setModuleNameAndNavigate = (moduleName) => {
    //     navigate(moduleName);
    // };

    const setModuleNameAndNavigate = (moduleName) => {
        window.location.href = moduleName;
    };


    return (
        <div>
            {/* Top Navbar  */}
            <nav className="navbar navbar-expand-lg navbar-dark woco-navbar">
                <div className="container-fluid">
                    <div className="text-center">
                        <img
                            src={woco}
                            alt="Company Logo"
                            className="img-fluid"
                            style={{ maxHeight: "50px" }}
                        />
                    </div>
                    <div>
                        <span className="navbar-brand fw-bold"> - FIFO System</span>
                        {/* <span>------------------------------------</span> */}

                    </div>

                    <div className="ms-auto text-white">
                        <span className="">Today: 06 Mar 2026 | Shift A</span><br />
                        <span className="">Welcome, User</span>
                    </div>
                </div>
            </nav>

            <div className="dashboard-bg">
                {/* <!-- Dashboard Section --> */}
                <div className="container py-5 position-relative">
                    <div className="row g-4">

                        {/* <!-- Master Database --> */}
                        <div className="col-md-6 col-lg-3">
                            <div className="module-card text-center">
                                <i className="bi bi-database-fill module-icon"></i>
                                <h5>Master Database</h5>
                                <Button
                                    variant="outline-secondary"
                                    size="sm"
                                    className="me-2 btn-woco"
                                    onClick={() => setModuleNameAndNavigate("/WebApplication/masterDashboard")}
                                    disabled={false}
                                > Open
                                </Button>
                            </div>
                        </div>

                        {/* <!-- Incoming Material --> */}
                        <div className="col-md-6 col-lg-3">
                            <div className="module-card text-center">
                                <i className="bi bi-database-fill module-icon"></i>
                                <h5>Quality Window</h5>

                                <Button
                                    variant="outline-secondary"
                                    size="sm"
                                    className="me-2 btn-woco"
                                    onClick={() => setModuleNameAndNavigate("/WebApplication/qualityIncoming")}
                                    disabled={false}
                                > Open
                                </Button>
                            </div>
                        </div>

                        {/* <!-- Outgoing Material --> */}
                        <div className="col-md-6 col-lg-3">
                            <div className="module-card text-center">
                                <i className="bi bi-database-fill module-icon"></i>
                                <h5>Quarantine Window</h5>
                                <Button
                                    variant="outline-secondary"
                                    size="sm"
                                    className="me-2 btn-woco"
                                    onClick={() => setModuleNameAndNavigate("/WebApplication/quarantineWindow")}
                                    disabled={false}
                                > Open
                                </Button>
                            </div>
                        </div>

                        {/* <!-- Production --> */}
                        <div className="col-md-6 col-lg-3">
                            <div className="module-card text-center module-disabled">
                                <i className="bi bi-gear-fill module-icon"></i>
                                <h5>Production</h5>
                                <Button
                                    variant="outline-secondary"
                                    size="sm"
                                    className="me-2 btn-woco"
                                    onClick={() => setModuleNameAndNavigate()}
                                    disabled={true}
                                > Access Restricted
                                </Button>
                            </div>
                        </div>

                        {/* <!-- Reports --> */}
                        <div className="col-md-6 col-lg-3">
                            <div className="module-card text-center">
                                <i className="bi bi-bar-chart-fill module-icon"></i>
                                <h5>Reports</h5>
                                <Button
                                    variant="outline-secondary"
                                    size="sm"
                                    className="me-2 btn-woco"
                                    onClick={() => setModuleNameAndNavigate("/WebApplication/reportDashboard")}
                                    disabled={false}
                                > Open
                                </Button>
                            </div>
                        </div>

                        {/* <!-- Inventory --> */}
                        <div className="col-md-6 col-lg-3">
                            <div className="module-card text-center module-disabled">
                                <i className="bi bi-box-seam-fill module-icon"></i>
                                <h5>Inventory</h5>
                                <Button
                                    variant="outline-secondary"
                                    size="sm"
                                    className="me-2 btn-woco"
                                    onClick={() => setModuleNameAndNavigate()}
                                    disabled={true}
                                > Access Restricted
                                </Button>
                            </div>
                        </div>

                        {/* <!-- Quality Check --> */}
                        <div className="col-md-6 col-lg-3">
                            <div className="module-card text-center module-disabled">
                                <i className="bi bi-shield-check module-icon"></i>
                                <h5>Quality Check</h5>
                                <Button
                                    variant="outline-secondary"
                                    size="sm"
                                    className="me-2 btn-woco"
                                    onClick={() => setModuleNameAndNavigate()}
                                    disabled={true}
                                > Access Restricted
                                </Button>
                            </div>
                        </div>

                        {/* <!-- Settings --> */}
                        <div className="col-md-6 col-lg-3">
                            <div className="module-card text-center module-disabled">
                                <i className="bi bi-gear-wide-connected module-icon"></i>
                                <h5>Settings</h5>
                                <Button
                                    variant="outline-secondary"
                                    size="sm"
                                    className="me-2 btn-woco"
                                    onClick={() => setModuleNameAndNavigate()}
                                    disabled={true}
                                > Access Restricted
                                </Button>
                            </div>
                        </div>

                    </div>
                </div>

                <div className="text-center text-white">
                    <a onClick={handleLogout} className="forgot-link mb-1">
                        ← Back to Login
                    </a>
                    <br />
                    <small>© 2026 Begapt Group</small>
                </div>

            </div>
        </div>
    );
};

export default ModuleDashboard;
