// ProductionArticleChildPartBomMaster.js
import React, { useEffect, useState, useContext, useCallback } from "react";
import axios from "axios";
import { Table, Button, Modal, Form } from "react-bootstrap";
import { useNavigate, useOutletContext } from "react-router-dom";
import { ClipboardList } from "lucide-react";
import "bootstrap/dist/css/bootstrap.min.css";
import "../css/Table.css";
import "../css/ModuleDashboard.css";
import SearchInputFields from "../components/SearchInputFields";
import Pager from "../components/Pager";
import LoadingSpinner from "../components/LoadingSpinner";
import { TrainingContext } from "./TrainingContext";
import { OverlayTrigger, Tooltip } from "react-bootstrap";
import { FaSearch } from "react-icons/fa";
import Select from "react-select";

const BASE_URL = process.env.REACT_APP_BASE_URL;

const ProductionArticleChildPartBomMaster = () => {
    const { setUploadUrl } = useContext(TrainingContext);

    const [loading, setLoading] = useState(true);

    // LEFT TABLE DATA
    const [tableData, setTableData] = useState([]);

    // RIGHT TABLE DATA
    const [childPartData, setChildPartData] = useState([]);
    const [processMasterData, setProcessMasterData] = useState([]);

    // selected article
    const [selectedArticle, setSelectedArticle] = useState(null);

    // Search Form
    const [formData, setFormData] = useState({
        productionArticleCategory: {
            articleCategory: ""
        },
        article: "",
        description: "",
        createdBy: "",
        dateTime: "",
        image: ""
    });

    // Pagination
    const [currentPage, setCurrentPage] = useState(0);
    const [totalPages, setTotalPages] = useState(0);
    const [pageSize, setPageSize] = useState(10);
    const [materialOptions, setMaterialOptions] = useState([]);
    const [loadingMaterials, setLoadingMaterials] = useState(false);
    const sequenceNumber = pageSize * currentPage;

    const navigate = useNavigate();
    const { setAlert, setStaticAlert, setReloadFunction } = useOutletContext();

    // =============================
    // CHILD PART MODAL STATES
    // =============================
    const [showChildModal, setShowChildModal] = useState(false);
    const [childRows, setChildRows] = useState([]);
    const [editChildObj, setEditChildObj] = useState(null);
    const [showEditChildModal, setShowEditChildModal] = useState(false);

    const openEditChildModal = (obj) => {
        fetchStoreMaterials();
        setEditChildObj(obj);
        setShowEditChildModal(true);
    };


    const deleteChildPart = async (id) => {
        if (!window.confirm("Are you sure you want to delete this Child Part?")) return;

        try {
            await axios.delete(
                BASE_URL + "/WebApplication/Controllers/deleteChildPart/" + id,
                { withCredentials: true }
            );

            alert("Deleted Successfully!");
            fetchRightSideData(selectedArticle);

        } catch (err) {
            console.log(err);
            alert("Delete Failed!");
        }
    };


const updateChildPart = async () => {
    try {
        const payload = {
            productionArticleBomId: editChildObj.productionArticleBomId,

            childPart: editChildObj.childPart?.material || editChildObj.childPart || "",

            // subChildPart: editChildObj.subChildPart?.material || editChildObj.subChildPart || "",

            description: editChildObj.description || "",
            issuenceCategory: editChildObj.issuenceCategory || "",
            status: editChildObj.status || "1"
        };

        await axios.put(
            BASE_URL + "/WebApplication/Controllers/updateChildPart",
            payload,
            { withCredentials: true }
        );

        alert("Updated Successfully!");
        setShowEditChildModal(false);
        fetchRightSideData(selectedArticle);

    } catch (err) {
        console.log(err);
        alert("Update Failed!");
    }
};

    const fetchStoreMaterials = async () => {
        try {
            setLoadingMaterials(true);

            const res = await axios.get(
                BASE_URL + "/WebApplication/Controllers/getAllStoreMaterial",
                { withCredentials: true }
            );

            console.log("responsestorematerial: ", res);

            const options = res.data.map((m) => ({
                value: m.material,
                label: m.material,
                description: m.description || ""
            }));

            setMaterialOptions(options);

        } catch (err) {
            console.log("Store Material fetch error:", err);
            setMaterialOptions([]);
        } finally {
            setLoadingMaterials(false);
        }
    };

    // =============================
    // PROCESS MODAL STATES
    // =============================
    const [showProcessModal, setShowProcessModal] = useState(false);
    const [processRows, setProcessRows] = useState([]);
    const [editProcessObj, setEditProcessObj] = useState(null);
    const [showEditProcessModal, setShowEditProcessModal] = useState(false);
    const [processOptions, setProcessOptions] = useState([]);
    const [loadingProcess, setLoadingProcess] = useState(false);

    const openEditProcessModal = (obj) => {
        fetchAllProcesses();
        setEditProcessObj(obj);
        setShowEditProcessModal(true);
    };

    const deleteProcess = async (id) => {
        if (!window.confirm("Are you sure you want to delete this Process?")) return;

        try {
            await axios.delete(
                BASE_URL + "/WebApplication/Controllers/deleteProcess/" + id,
                { withCredentials: true }
            );

            alert("Deleted Successfully!");
            fetchRightSideData(selectedArticle);

        } catch (err) {
            console.log(err);
            alert("Delete Failed!");
        }
    };

const updateProcess = async () => {
    try {
        const payload = {
            productionArticleRouteId: editProcessObj.productionArticleRouteId,
            process: editProcessObj.process?.processName  || editProcessObj.process || "",
            description: editProcessObj.description || "",
            status: editProcessObj.status || "1"
        };

        await axios.put(
            BASE_URL + "/WebApplication/Controllers/updateProcess",
            payload,
            { withCredentials: true }
        );

        alert("Updated Successfully!");
        setShowEditProcessModal(false);
        fetchRightSideData(selectedArticle);

    } catch (err) {
        console.log(err);
        alert("Update Failed!");
    }
};


    const fetchAllProcesses = async () => {
        try {
            setLoadingProcess(true);

            const res = await axios.get(
                BASE_URL + "/WebApplication/Controllers/getAllProcessMaster",
                { withCredentials: true }
            );

            console.log("processresponse: ",res);

            const options = res.data.map((p) => ({
                value: p.processName,
                label: p.processName,
                description: p.description || ""
            }));

            setProcessOptions(options);

        } catch (err) {
            console.log("Process fetch error:", err);
            setProcessOptions([]);
        } finally {
            setLoadingProcess(false);
        }
    };

    // =============================
    // HANDLE SEARCH FORM
    // =============================
    const handleChange = (e) => {
        const { name, value } = e.target;
        const keys = name.split(".");

        setFormData((prev) => {
            const updated = { ...prev };
            let current = updated;

            keys.forEach((key, index) => {
                if (index === keys.length - 1) {
                    current[key] = value;
                } else {
                    current[key] = { ...current[key] };
                    current = current[key];
                }
            });

            return updated;
        });
    };

    // =============================
    // LOAD LEFT TABLE DATA
    // =============================
    const loadTableData = useCallback(async () => {
        try {
            setLoading(true);

            const response = await axios.post(
                BASE_URL + "/WebApplication/Controllers/getLikesproductionArticle/" + currentPage + "/" + pageSize,
                formData,
                { withCredentials: true }
            );

            console.log("Data Load Successfully:", response);

            setTableData(response.data.content);
            setTotalPages(response.data.totalPages);
            setCurrentPage(response.data.pageable.pageNumber);
        } catch (error) {
            console.log(error);
        } finally {
            setLoading(false);
        }
    }, [formData, currentPage, pageSize]);

    useEffect(() => {
        if (setReloadFunction) {
            setReloadFunction(() => loadTableData);
        }
    }, [loadTableData]);

    useEffect(() => {
        loadTableData();
    }, [currentPage, pageSize]);

    const handleEnterKey = (e, callback) => {
        if (e.key === "Enter") {
            e.preventDefault();
            callback();
        }
    };

    // =============================
    // FETCH RIGHT SIDE DATA
    // =============================
    const fetchRightSideData = async (articleObj) => {
        try {
            setSelectedArticle(articleObj);

            // Child Part Data
            const childRes = await axios.get(
                BASE_URL +
                "/WebApplication/Controllers/getChildPartByArticle/" +
                articleObj.productionArticleId,
                { withCredentials: true }
            );

            setChildPartData(childRes.data || []);

            // Process Master Data
            const processRes = await axios.get(
                BASE_URL +
                "/WebApplication/Controllers/getProcessByArticle/" +
                articleObj.productionArticleId,
                { withCredentials: true }
            );

            setProcessMasterData(processRes.data || []);
        } catch (error) {
            console.log("Right side fetch error:", error);
            setChildPartData([]);
            setProcessMasterData([]);
        }
    };

    // =============================
    // CHILD PART MODAL FUNCTIONS
    // =============================
    const openChildPartModal = () => {
        if (!selectedArticle) {
            alert("Please select an Article first!");
            return;
        }

        fetchStoreMaterials();

        setChildRows([
            {
                childPart: "",
          
                description: "",
                issuenceCategory: ""
            }
        ]);

        setShowChildModal(true);
    };

    const addChildRow = () => {
        setChildRows((prev) => [
            ...prev,
            {
                childPart: "",
      
                description: "",
                issuenceCategory: ""
            }
        ]);
    };

    const removeChildRow = (index) => {
        setChildRows((prev) => prev.filter((_, i) => i !== index));
    };

    const handleChildRowChange = (index, field, value) => {
        setChildRows((prev) =>
            prev.map((row, i) => (i === index ? { ...row, [field]: value } : row))
        );
    };

    const saveChildParts = async () => {
        try {
            if (!selectedArticle) return;

            const payload = {
                articleId: selectedArticle.productionArticleId,
                articleNo: selectedArticle.mould,
                childParts: childRows
            };

            console.log("ChildPart Save Payload:", payload);

            await axios.post(
                BASE_URL + "/WebApplication/Controllers/saveArticleChildParts",
                payload,
                { withCredentials: true }
            );

            alert("Child Parts Saved Successfully!");

            setShowChildModal(false);

            // refresh right table
            fetchRightSideData(selectedArticle);
        } catch (err) {
            console.log(err);
            alert("Child Part Save Failed!");
        }
    };


    const updateChildPartStatus = async (id, checked) => {
        try {
            const status = checked ? "1" : "0";

            await axios.put(
                BASE_URL + "/WebApplication/Controllers/updateProductionArticleBomStatus/" + id + "/" + status,
                {},
                { withCredentials: true }
            );

            fetchRightSideData(selectedArticle);

        } catch (err) {
            console.log(err);
            alert("Status update failed!");
        }
    };

    // =============================
    // PROCESS MODAL FUNCTIONS
    // =============================
    const openProcessModal = () => {
        if (!selectedArticle) {
            alert("Please select an Article first!");
            return;
        }

         fetchAllProcesses();

        setProcessRows([{ process: "", description: "" }]);
        setShowProcessModal(true);
    };

    const addProcessRow = () => {
        setProcessRows((prev) => [...prev, { process: "", description: "" }]);
    };

    const removeProcessRow = (index) => {
        setProcessRows((prev) => prev.filter((_, i) => i !== index));
    };

    const handleProcessRowChange = (index, field, value) => {
        setProcessRows((prev) =>
            prev.map((row, i) => (i === index ? { ...row, [field]: value } : row))
        );
    };

    const saveProcesses = async () => {
        try {
            if (!selectedArticle) return;

            const payload = {
                articleId: selectedArticle.productionArticleId,
                articleNo: selectedArticle.mould,
                processes: processRows
            };

            console.log("Process Save Payload:", payload);

            await axios.post(
                BASE_URL + "/WebApplication/Controllers/saveArticleProcesses",
                payload,
                { withCredentials: true }
            );

            alert("Process Saved Successfully!");

            setShowProcessModal(false);

            fetchRightSideData(selectedArticle);
        } catch (err) {
            console.log(err);
            alert("Process Save Failed!");
        }
    };

    const modalHeaderStyle = {
        background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
        color: "white"
    };

    const modalTitleStyle = {
        fontWeight: "700",
        letterSpacing: "0.5px"
    };

    const modalFooterStyle = {
        background: "#f4f6f8",
        borderTop: "1px solid #dcdcdc"
    };

    const selectStyle = {
        control: (base) => ({
            ...base,
            minHeight: "32px",
            fontSize: "13px"
        }),
        menu: (base) => ({
            ...base,
            zIndex: 9999
        })
    };

    const showUploadModal = (type) => {
    setStaticAlert({ type: "success", message: "Please upload Excel file..." });

    if (type === "CHILDPART") {
        setUploadUrl("uploadproductionarticlebom");  
    }

    if (type === "PROCESS") {
        setUploadUrl("uploadproductionArticleroute"); 
    }
};

    // =============================
    // MAIN RETURN UI
    // =============================
    return (
        <div
            className="card shadow-lg rounded-0 border-0 bg-light d-flex flex-column p-2"
            style={{
                width: "100%",
                minHeight: "100vh",
                background: "#f4f6f8"
            }}
        >
            {/* Header */}
            <div
                className="px-4 py-2"
                style={{
                    background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                    color: "white"
                }}
            >
                <h4 className="text-end fw-bold mb-0">
                    <ClipboardList
                        size={30}
                        viewBox="0 1 24 24"
                        className="me-2 text-white"
                    />
                    Production Article Child Part BOM Master
                </h4>
            </div>

            {/* MAIN CONTENT */}
            <div className="row g-2 px-1 mt-1" style={{ height: "80vh" }}>
                {/* LEFT SIDE ARTICLE TABLE */}
                <div className="col-md-4 h-100">
                    <div className="card shadow-sm border-0 h-100">
                        <div
                            className="card-header fw-bold text-white"
                            style={{
                                background: "linear-gradient(360deg, #0f6b5b, #0b4f43)"
                            }}
                        >
                            Article
                        </div>

                        <div className="card-body p-1" style={{ overflowY: "auto" }}>
                            {loading ? (
                                <LoadingSpinner message={`Loading .....`} />
                            ) : (
                                <Table
                                    bordered
                                    hover
                                    responsive
                                    className="align-middle shadow-sm rounded custom-table"
                                >
                                    <thead className="bg-light sticky-top">
                                        <tr>
                                            <th colSpan={2}>
                                                <div className="input-group w-100 flex-nowrap">
                                                    <Button
                                                        className="btn btn-success btn-woco"
                                                        onClick={loadTableData}
                                                        style={{ whiteSpace: "nowrap" }}
                                                    >
                                                        <FaSearch className="me-1" />
                                                    </Button>

                                                    <div className="flex-grow-1">
                                                        <SearchInputFields
                                                            type="text"
                                                            placeholder="Search Article"
                                                            name="article"
                                                            onChange={(e) => handleChange(e)}
                                                            value={formData?.article}
                                                            onKeyDown={(e) => handleEnterKey(e, loadTableData)}
                                                            className="w-100"
                                                        />
                                                    </div>
                                                </div>
                                            </th>
                                        </tr>
                                    </thead>

                                    <thead style={{ backgroundColor: "#0f6b5b", color: "#fff" }}>
                                        <tr>
                                            <th>S.No</th>
                                            <th>Article</th>
                                            <th>Description</th>
                                        </tr>
                                    </thead>

                                    <tbody>
                                        {Array.isArray(tableData) && tableData.length > 0 ? (
                                            tableData.map((object, i) => (
                                                <tr
                                                    key={object.productionArticleId}
                                                    style={{
                                                        cursor: "pointer",
                                                        background:
                                                            selectedArticle?.productionArticleId === object.productionArticleId
                                                                ? "#d9f3ef"
                                                                : "white",
                                                        fontWeight:
                                                            selectedArticle?.productionArticleId === object.productionArticleId
                                                                ? "700"
                                                                : "400",
                                                        borderLeft:
                                                            selectedArticle?.productionArticleId === object.productionArticleId
                                                                ? "5px solid #0f6b5b"
                                                                : "5px solid transparent"
                                                    }}
                                                    onClick={() => fetchRightSideData(object)}
                                                >
                                                    <td>{sequenceNumber + i + 1}</td>
                                                    <td>{object.article}</td>
                                                    <td>{object.description}</td>
                                                </tr>
                                            ))
                                        ) : (
                                            <tr>
                                                <td colSpan="2" className="text-center">
                                                    No Data Available
                                                </td>
                                            </tr>
                                        )}
                                    </tbody>
                                </Table>
                            )}
                        </div>
                    </div>
                </div>

                {/* RIGHT SIDE TABLES */}
                <div className="col-md-8 h-100">
                    <div className="d-flex flex-column h-100" style={{ gap: "10px" }}>
                        {/* TOP RIGHT - CHILD PART TABLE */}
                        <div className="card shadow-sm border-0" style={{ flex: 1 }}>
                            <div
                                className="card-header d-flex justify-content-between align-items-center text-white fw-bold"
                                style={{
                                    background: "linear-gradient(360deg, #0f6b5b, #0b4f43)"
                                }}
                            >
                                Article Child Part Table

                                <div className="d-flex gap-2">
    <Button size="sm" className="btn btn-light" onClick={openChildPartModal}>
        Add
    </Button>

    <Button
        size="sm"
        className="btn btn-warning"
        onClick={() =>
            window.open(
                BASE_URL + "/WebApplication/Controllers/download/template/productionArticleBom",
                "_blank"
            )
        }
    >
        Download Template
    </Button>

    <Button
        size="sm"
        className="btn btn-info text-white"
        onClick={() => showUploadModal("CHILDPART")}
    >
        Upload Excel
    </Button>
</div>
                            </div>

                            <div className="card-body p-1" style={{ overflowY: "auto" }}>
                                <Table bordered hover responsive className="table table-sm">
                                    <thead style={{ backgroundColor: "#0f6b5b", color: "#fff" }}>
                                        <tr>
                                            <th>Action</th>
                                            <th>S.No</th>
                                            <th>Child Part</th>
                                            <th>Description</th>
                                            <th>Issuence Category</th>
                                            <th>Status</th>
                                        </tr>
                                    </thead>

                                    <tbody>
                                        {childPartData.length > 0 ? (
                                            childPartData.map((obj, i) => (
                                                <tr key={obj.productionArticleBomId || i}>
                                                    <td>
                                                        <Button
                                                            size="sm"
                                                            className="me-1 btn btn-warning"
                                                            onClick={() => openEditChildModal(obj)}
                                                        >
                                                            Edit
                                                        </Button>

                                                        <Button
                                                            size="sm"
                                                            className="btn btn-danger"
                                                            onClick={() => deleteChildPart(obj.productionArticleBomId)}
                                                        >
                                                            Delete
                                                        </Button>
                                                    </td>

                                                    <td>{i + 1}</td>
                                                    <td>{obj.childPart?.material || obj.childPart || "-"}</td>
                                              
                                                    <td>{obj.description}</td>
                                       
                                                    <td>{obj.issuenceCategory}</td>
                                                    <td className="text-center">
                                                        <Form.Check
                                                            type="checkbox"
                                                            checked={obj.status === "1"}
                                                            onChange={(e) =>
                                                                updateChildPartStatus(obj.productionArticleBomId, e.target.checked)
                                                            }
                                                        />
                                                    </td>
                                                </tr>
                                            ))
                                        ) : (
                                            <tr>
                                                <td colSpan="7" className="text-center text-muted fw-bold">
                                                    Select Article to View Child Parts
                                                </td>
                                            </tr>
                                        )}
                                    </tbody>
                                </Table>
                            </div>
                        </div>

                        {/* BOTTOM RIGHT - PROCESS MASTER TABLE */}
                        <div className="card shadow-sm border-0" style={{ flex: 1 }}>
                            <div
                                className="card-header d-flex justify-content-between align-items-center text-white fw-bold"
                                style={{
                                    background: "linear-gradient(360deg, #0f6b5b, #0b4f43)"
                                }}
                            >
                                Article Process Master Table

                            <div className="d-flex gap-2">
    <Button size="sm" className="btn btn-light" onClick={openProcessModal}>
        Add
    </Button>

    <Button
        size="sm"
        className="btn btn-warning"
        onClick={() =>
            window.open(
                BASE_URL + "/WebApplication/Controllers/download/template/productionArticleRoute",
                "_blank"
            )
        }
    >
        Download Template
    </Button>

    <Button
        size="sm"
        className="btn btn-info text-white"
        onClick={() => showUploadModal("PROCESS")}
    >
        Upload Excel
    </Button>
</div>
                            </div>

                            <div className="card-body p-1" style={{ overflowY: "auto" }}>
                                <Table bordered hover responsive className="table table-sm">
                                    <thead style={{ backgroundColor: "#0f6b5b", color: "#fff" }}>
                                        <tr>
                                            <th>Action</th>
                                            <th>S.No</th>
                                            <th>Process</th>
                                            <th>Description</th>
                                         
                                        </tr>
                                    </thead>

                                    <tbody>
                                        {processMasterData.length > 0 ? (
                                            processMasterData.map((obj, i) => (
                                                <tr key={obj.productionArticleRouteId || i}>
                                                    <td>
                                                        <Button
                                                            size="sm"
                                                            className="me-1 btn btn-warning"
                                                            onClick={() => openEditProcessModal(obj)}
                                                        >
                                                            Edit
                                                        </Button>

                                                        <Button
                                                            size="sm"
                                                            className="btn btn-danger"
                                                            onClick={() => deleteProcess(obj.productionArticleRouteId)}
                                                        >
                                                            Delete
                                                        </Button>
                                                    </td>

                                                    <td>{i + 1}</td>
                                                    <td>{obj.process?.processName || obj.processName || "-"}</td>
                                                     <td>{obj.process?.description || obj.description || "-"}</td>
                                       
                                                </tr>
                                            ))
                                        ) : (
                                            <tr>
                                                <td colSpan="5" className="text-center text-muted fw-bold">
                                                    Select Article to View Process Master
                                                </td>
                                            </tr>
                                        )}
                                    </tbody>
                                </Table>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* FOOTER PAGER */}
            <div
                className="row mt-2 mt-auto m-1"
                style={{
                    background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                    color: "white"
                }}
            >
                <div className="col-md-12 align-items-center radius-2">
                    <div className="m-2">
                        <Pager
                            currentPage={currentPage}
                            totalPages={totalPages}
                            onPageChange={setCurrentPage}
                            pageSize={pageSize}
                            onPageSizeChange={setPageSize}
                        />
                    </div>
                </div>
            </div>

            {/* ===================== CHILD PART MODAL ===================== */}
            <Modal show={showChildModal} onHide={() => setShowChildModal(false)} size="xl" centered>
                <Modal.Header closeButton style={modalHeaderStyle}>
                    <Modal.Title style={modalTitleStyle}>
                        Add Child Parts (Article: {selectedArticle?.article})
                    </Modal.Title>
                </Modal.Header>

                <Modal.Body style={{ background: "#f9fafb" }}>
                    <div className="p-2 rounded shadow-sm bg-white">
                        <Table bordered responsive className="table table-sm align-middle">
                            <thead style={{ backgroundColor: "#0f6b5b", color: "#fff" }}>
                                <tr>
                                    <th style={{ width: "50px" }}>S No.</th>
                                    <th>Child Part</th>
                               
                                    <th>Description</th>
                                    <th style={{ width: "200px" }}>Issuence Category</th>
                                    <th style={{ width: "90px" }}>Remove</th>
                                </tr>
                            </thead>

                            <tbody>
                                {childRows.map((row, index) => (
                                    <tr key={index}>
                                        <td className="fw-bold">{index + 1}</td>

                                        <td>
                                            <Select
                                                options={materialOptions}
                                                styles={{
                                                    ...selectStyle,
                                                    menuPortal: (base) => ({ ...base, zIndex: 999999 }),
                                                    menu: (base) => ({ ...base, zIndex: 999999 })
                                                }}
                                                menuPortalTarget={document.body}
                                                menuPosition="fixed"
                                                isSearchable={true}
                                                isLoading={loadingMaterials}
                                                placeholder="Search Child Part..."
                                                value={materialOptions.find(opt => opt.value === row.childPart) || null}
                                                onChange={(selected) => {
                                                    handleChildRowChange(index, "childPart", selected ? selected.value : "");
                                                    handleChildRowChange(index, "description", selected ? selected.description : "");
                                                }}
                                            />
                                        </td>

                                        <td>
                                            <Form.Control
                                                placeholder="Enter Description"
                                                value={row.description}
                                                onChange={(e) =>
                                                    handleChildRowChange(index, "description", e.target.value)
                                                }
                                            />
                                        </td>

                                        <td>
                                            <Form.Select
                                                value={row.issuenceCategory}
                                                onChange={(e) =>
                                                    handleChildRowChange(index, "issuenceCategory", e.target.value)
                                                }
                                            >
                                                <option value="">-- Select --</option>
                                                <option value="PRODUCTION">Production</option>
                                                <option value="MIXINGMILL">Mixingmill</option>
                                                <option value="ARTICLE">Article</option>
                                            </Form.Select>
                                        </td>

                                        <td className="text-center">
                                            <Button
                                                size="sm"
                                                variant="danger"
                                                className="fw-bold"
                                                onClick={() => removeChildRow(index)}
                                            >
                                                ✖
                                            </Button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </Table>

                        <div className="d-flex justify-content-end">
                            <Button variant="success" className="fw-bold" onClick={addChildRow}>
                                + Add Row
                            </Button>
                        </div>
                    </div>
                </Modal.Body>

                <Modal.Footer style={modalFooterStyle}>
                    <Button variant="secondary" onClick={() => setShowChildModal(false)}>
                        Close
                    </Button>

                    <Button
                        style={{
                            background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                            border: "none",
                            fontWeight: "700"
                        }}
                        onClick={saveChildParts}
                    >
                        Save Child Parts
                    </Button>
                </Modal.Footer>
            </Modal>
            {/* ===================== PROCESS MODAL ===================== */}
            <Modal show={showProcessModal} onHide={() => setShowProcessModal(false)} size="lg" centered>
                <Modal.Header closeButton style={modalHeaderStyle}>
                    <Modal.Title style={modalTitleStyle}>
                        Add Process Master (Article: {selectedArticle?.article})
                    </Modal.Title>
                </Modal.Header>

                <Modal.Body style={{ background: "#f9fafb" }}>
                    <div className="p-2 rounded shadow-sm bg-white">
                        <Table bordered responsive className="table table-sm align-middle">
                            <thead style={{ backgroundColor: "#0f6b5b", color: "#fff" }}>
                                <tr>
                                    <th style={{ width: "50px" }}>S No.</th>
                                    <th>Process</th>
                                    <th>Description</th>
                                    <th style={{ width: "90px" }}>Remove</th>
                                </tr>
                            </thead>

                            <tbody>
                                {processRows.map((row, index) => (
                                    <tr key={index}>
                                        <td className="fw-bold">{index + 1}</td>
                                        <td>
                                            <Select
                                                options={processOptions}
                                                styles={{
                                                    ...selectStyle,
                                                    menuPortal: (base) => ({ ...base, zIndex: 999999 }),
                                                    menu: (base) => ({ ...base, zIndex: 999999 })
                                                }}
                                                menuPortalTarget={document.body}
                                                menuPosition="fixed"
                                                isSearchable={true}
                                                isLoading={loadingProcess}
                                                placeholder="Search Process..."
                                                value={processOptions.find(opt => opt.value === row.processName) || null}
                                                onChange={(selected) => {
                                                    handleProcessRowChange(index, "processName", selected ? selected.value : "");
                                                    handleProcessRowChange(index, "description", selected ? selected.description : "");
                                                }}
                                            />
                                        </td>

                                        <td>
                                            <Form.Control
                                                placeholder="Enter Description"
                                                value={row.description}
                                                onChange={(e) =>
                                                    handleProcessRowChange(index, "description", e.target.value)
                                                }
                                            />
                                        </td>

                                        <td className="text-center">
                                            <Button
                                                size="sm"
                                                variant="danger"
                                                className="fw-bold"
                                                onClick={() => removeProcessRow(index)}
                                            >
                                                ✖
                                            </Button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </Table>

                        <div className="d-flex justify-content-end">
                            <Button variant="success" className="fw-bold" onClick={addProcessRow}>
                                + Add Row
                            </Button>
                        </div>
                    </div>
                </Modal.Body>

                <Modal.Footer style={modalFooterStyle}>
                    <Button variant="secondary" onClick={() => setShowProcessModal(false)}>
                        Close
                    </Button>

                    <Button
                        style={{
                            background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                            border: "none",
                            fontWeight: "700"
                        }}
                        onClick={saveProcesses}
                    >
                        Save Process
                    </Button>
                </Modal.Footer>
            </Modal>

            {/* EditChildPartModel */}


            <Modal show={showEditChildModal} onHide={() => setShowEditChildModal(false)} size="lg" centered>
                <Modal.Header closeButton style={modalHeaderStyle}>
                    <Modal.Title style={modalTitleStyle}>Edit Child Part</Modal.Title>
                </Modal.Header>

                <Modal.Body>
                    <Form.Group className="mb-2">
                        <Form.Label>Child Part</Form.Label>
                        <Select
                            options={materialOptions}
                            styles={{
                                ...selectStyle,
                                menuPortal: (base) => ({ ...base, zIndex: 999999 }),
                                menu: (base) => ({ ...base, zIndex: 999999 })
                            }}
                            menuPortalTarget={document.body}
                            menuPosition="fixed"
                            isSearchable={true}
                            isLoading={loadingMaterials}
                            placeholder="Search Child Part..."
                            value={materialOptions.find(opt => opt.value === editChildObj?.childPart) || null}
                            onChange={(selected) =>
                                setEditChildObj({
                                    ...editChildObj,
                                    childPart: selected ? selected.value : "",
                                    description: selected ? selected.description : editChildObj?.description
                                })
                            }
                        />
                    </Form.Group>


                    <Form.Group className="mb-2">
                        <Form.Label>Description</Form.Label>
                        <Form.Control
                            value={editChildObj?.description || ""}
                            onChange={(e) =>
                                setEditChildObj({ ...editChildObj, description: e.target.value })
                            }
                        />
                    </Form.Group>

                    <Form.Group className="mb-2">
                        <Form.Label>Issuence Category</Form.Label>
                        <Form.Select
                            value={editChildObj?.issuenceCategory || ""}
                            onChange={(e) =>
                                setEditChildObj({
                                    ...editChildObj,
                                    issuenceCategory: e.target.value
                                })
                            }
                        >
                            <option value="">-- Select --</option>
                            <option value="PRODUCTION">Production</option>
                            <option value="MIXINGMILL">Mixingmill</option>
                            <option value="ARTICLE">Article</option>
                        </Form.Select>
                    </Form.Group>

                    <Form.Group className="mb-2">
                        <Form.Label>Status</Form.Label>
                        <Form.Select
                            value={editChildObj?.status || ""}
                            onChange={(e) =>
                                setEditChildObj({ ...editChildObj, status: e.target.value })
                            }
                        >
                            <option value="1">Active</option>
                            <option value="0">Inactive</option>
                        </Form.Select>
                    </Form.Group>
                </Modal.Body>


                <Modal.Footer style={modalFooterStyle}>
                    <Button variant="secondary" onClick={() => setShowEditChildModal(false)}>
                        Close
                    </Button>

                    <Button
                        style={{
                            background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                            border: "none",
                            fontWeight: "700"
                        }}
                        onClick={updateChildPart}
                    >
                        Update
                    </Button>
                </Modal.Footer>
            </Modal>



            {/* EditProcessModel */}


            <Modal show={showEditProcessModal} onHide={() => setShowEditProcessModal(false)} size="lg" centered>
                <Modal.Header closeButton style={modalHeaderStyle}>
                    <Modal.Title style={modalTitleStyle}>Edit Process</Modal.Title>
                </Modal.Header>

                <Modal.Body>
                    <Form.Group className="mb-2">
                        <Form.Label>Process</Form.Label>
                        <Select
                            options={processOptions}
                            styles={{
                                ...selectStyle,
                                menuPortal: (base) => ({ ...base, zIndex: 999999 }),
                                menu: (base) => ({ ...base, zIndex: 999999 })
                            }}
                            menuPortalTarget={document.body}
                            menuPosition="fixed"
                            isSearchable={true}
                            isLoading={loadingProcess}
                            placeholder="Search Process..."
                            value={processOptions.find(opt => opt.value === editProcessObj?.process?.processName) || null}
                            onChange={(selected) =>
                                setEditProcessObj({
                                    ...editProcessObj,
                                    processName: { processName: selected ? selected.value : "" },
                                    description: selected ? selected.description : editProcessObj?.description
                                })
                            }
                        />
                    </Form.Group>

                    <Form.Group className="mb-2">
                        <Form.Label>Description</Form.Label>
                        <Form.Control
                            value={editProcessObj?.description || ""}
                            onChange={(e) =>
                                setEditProcessObj({ ...editProcessObj, description: e.target.value })
                            }
                        />
                    </Form.Group>

                    <Form.Group className="mb-2">
                        <Form.Label>Status</Form.Label>
                        <Form.Select
                            value={editProcessObj?.status || ""}
                            onChange={(e) =>
                                setEditProcessObj({ ...editProcessObj, status: e.target.value })
                            }
                        >
                            <option value="1">Active</option>
                            <option value="0">Inactive</option>
                        </Form.Select>
                    </Form.Group>
                </Modal.Body>

                <Modal.Footer style={modalFooterStyle}>
                    <Button variant="secondary" onClick={() => setShowEditProcessModal(false)}>
                        Close
                    </Button>

                    <Button
                        style={{
                            background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                            border: "none",
                            fontWeight: "700"
                        }}
                        onClick={updateProcess}
                    >
                        Update
                    </Button>
                </Modal.Footer>
            </Modal>



        </div>
    );
};

export default ProductionArticleChildPartBomMaster;

