import React, { useState, useEffect } from "react";
import InputField from "../components/InputFields";
import myLogo from "../images/default2.png";
import { Link } from "react-router-dom";
import axios from "axios";
import { ArrowLeft } from "react-bootstrap-icons";
import { useLocation } from "react-router-dom";
import { useOutletContext } from "react-router-dom";
import LoadingSpinner from "../components/LoadingSpinner";
import { ClipboardList } from "lucide-react";
const BASE_URL = process.env.REACT_APP_BASE_URL;

const NewProductionCompoundChildPartForm = () => {
    const [loading, setLoading] = useState(true);
const [productionCompoundChildPartId, setProductionCompoundChildPartId] = useState("");
const [productionCompoundId, setProductionCompoundId] = useState("");
const [acceleraters, setAcceleraters] = useState("");
const [unit, setUnit] = useState("");
    const [error, setError] = useState("");
    const { setAlert } = useOutletContext();
    const location = useLocation();
    const { object } = location.state || {};
    const [selectedImage, setSelectedImage] = useState(null); // real File
    const [previewUrl, setPreviewUrl] = useState(null);
    const [image, setImage] = useState(null);   
    const [batchCutting, setBatchCutting] = useState(0);
const [rmsWeight, setRmsWeight] = useState(0);  
const [compoundList, setCompoundList] = useState([]);
const [compoundName, setCompoundName] = useState("");  // preview

    const handleImageChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            setSelectedImage(file); // 👈 real File object
            setPreviewUrl(URL.createObjectURL(file)); // 👈 preview blob URL
        } else {
            alert("Please Select a JPG and PNG image.");
        }
    };

    useEffect(() => {
    const fetchCompounds = async () => {
        try {
            const res = await axios.post(
                BASE_URL + "/WebApplication/Controllers/getProductionCompound/0/1000",
                {},
                { withCredentials: true }
            );

            setCompoundList(res.data.content);
        } catch (err) {
            console.error(err);
        }
    };

    fetchCompounds();
}, []);

    useEffect(() => {
        
        if (object) {
          setProductionCompoundChildPartId(object.productionCompoundChildPartId || "");

        const comp = object.productionCompoundMaster;
        if (comp) {
            setProductionCompoundId(comp.productionCompoundId);
            setCompoundName(comp.compound); // 👈 IMPORTANT
        }

        setAcceleraters(object.acceleraters || "");
        setUnit(object.unit || "");
        setImage(object.image || "");
        setPreviewUrl(object.image || "");
//         setBatchCutting(object.batchCutting === "1" ? 1 : 0);
// setRmsWeight(object.rmsWeight === "1" ? 1 : 0);
        }

        setLoading(false);
    }, [object]);

const resetForm = () => {
    setProductionCompoundChildPartId("");
    setProductionCompoundId("");
    setAcceleraters("");
    setUnit("");

    setSelectedImage(null);
    setPreviewUrl(null);
    setImage(null);

    setError("");
};


    const handleUploadAndSubmit = async (e) => {
        e.preventDefault();
        try {

            if (!selectedImage) {
                // alert("Please select an image first!");
                await handleSubmitForm(e);
                return;
            } else {

                const imageData = new FormData();
                imageData.append("image", selectedImage);

                const response = await axios.post(
                    BASE_URL + "/WebApplication/Controllers/uploadImage",
                    imageData,
                    { headers: { "Content-Type": "multipart/form-data" } }
                );
                alert("Image uploaded successfully!");

                // ✅ Directly pass the uploaded image name/path
                await handleSubmitForm(e, response.data);
                return;
            }

        } catch (error) {
            console.error("Error uploading:", error);
        }
    };

const formatDate = (dateStr) => {
    if (!dateStr) return "";
    const [year, month, day] = dateStr.split("-");
    return `${day}-${month}-${year}`;
};

    const isBlankOrSpaces = (value = "") =>
        value.trim().length === 0;

const handleSubmitForm = async (e, uploadedImage) => {
    e.preventDefault();

    if (!productionCompoundId || !acceleraters.trim()) {
        alert("Please fill required fields");
        return;
    }

    const selected = compoundList.find(
    (item) => item.compound === compoundName
);

if (!selected) {
    alert("Please select valid compound from list");
    return;
}

    const data = {
        productionCompoundChildPartId: productionCompoundChildPartId
            ? parseInt(productionCompoundChildPartId)
            : null,

        productionCompoundMaster: {
            productionCompoundId: parseInt(productionCompoundId)
        },

        acceleraters,
        unit,

        image: uploadedImage
            ? "/WebApplication/trainingResouces/" + uploadedImage + ".png"
            : image,

        createdBy: "111",
    };

    try {
        const url = object
            ? BASE_URL + "/WebApplication/Controllers/updateProductionCompoundChildPart"
            : BASE_URL + "/WebApplication/Controllers/insertProductionCompoundChildPart";

        const response = await axios.post(url, data, { withCredentials: true });

        setAlert({ type: "success", message: "Success: " + response.data });
    } catch (err) {
        setAlert({ type: "danger", message: "Error: " + err.response?.data });
    }
};

    return (
        <div className="card shadow-lg rounded-0 border-0 bg-light d-flex flex-column p-2"
            style={{
                width: "100%",
                minHeight: "100vh",
                background: "#f4f6f8",
            }}>
            {/* Header */}
            <div className="px-4 py-2 position-relative"
                style={{
                    background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                    color: "white"
                }}>
                {/* Title */}
                <h4 className="text-end fw-bold mb-0"><ClipboardList size={30} viewBox="0 1 24 24" className="me-2 text-white" />
                    {object ? "Update Child Part" : "New Child Part"}</h4>
                <div
                    className="position-absolute top-50 start-0 translate-middle-y ms-3"
                    style={{ zIndex: 10 }}
                >
                    <Link
                        to="/WebApplication/masterDashboard/productionCompoundChildPartMaster"
                        className="btn btn-light btn-sm d-flex align-items-center fw-semibold shadow-sm"
                    >
                        <ArrowLeft className="me-1" /><span className="d-none d-lg-inline">Back</span>
                    </Link>
                </div>
            </div>


            {error && <p className="text-danger text-center fw-semibold mt-2">{error}</p>}

            {loading ? (
                <LoadingSpinner message={`Loading .....`} />
            ) : (

                <div className="row g-1 p-1" style={{ maxHeight: "90vh", overflowY: "scroll" }}>

                    {/* Right Side - Illustration */}
                    <div className="col-md-4 bg-light rounded-3 shadow-sm">
                        <div className="d-flex justify-content-center align-items-center h-100">
                            <img
                                src={previewUrl || myLogo}  // 👈 replace with uploaded file if exists
                                alt="Project Illustration"
                                className="img-fluid"
                                style={{ maxWidth: "80%", opacity: 0.95 }}
                            />
                        </div>
                    </div>

                    {/* Left Side - Form */}
                    <div className="col-md-8" >
                        <form onSubmit={handleUploadAndSubmit} className="p-2 bg-light rounded-3 shadow-sm" style={{ height: "87vh", overflow: "auto" }}>
                            <div className="row g-1">
                                {/* Plant Name. */}

<div className="row g-1">
<div className="col-md-6 px-2">
    <label className="form-label fw-semibold">Compound</label>

    <input
        type="text"
        className="form-control"
        list="compoundList"
        value={compoundName}
        onChange={(e) => {
            const value = e.target.value;
            setCompoundName(value);

            const selected = compoundList.find(
                (item) => item.compound === value
            );

            if (selected) {
                setProductionCompoundId(selected.productionCompoundId); // 👈 SET ID
            }
        }}
        placeholder="Select Compound"
        required
    />

    <datalist id="compoundList">
        {compoundList.map((item) => (
            <option key={item.productionCompoundId} value={item.compound} />
        ))}
    </datalist>
</div>

    <div className="col-md-6 px-2">
        <InputField
            label="Acceleraters"
            type="text"
            value={acceleraters}
            onChange={(e) => setAcceleraters(e.target.value)}
            required
        />
    </div>

    <div className="col-md-6 px-2">
        <InputField
            label="Unit"
            type="text"
            value={unit}
            onChange={(e) => setUnit(e.target.value)}
        />
    </div>

    <div className="col-md-6 px-2">
        <InputField
            label="Image"
            type="file"
            accept="image/png, image/jpeg"
            onChange={handleImageChange}
        />
    </div>

</div>

                                {/* Save Button */}
                                <div className="col-md-4 p-2">
                                    <button
                                        type="submit"
                                        size="lr"
                                        className="btn-woco btn btn-light btn-sm 
                                                    d-flex align-items-center 
                                                    fw-semibold shadow-sm"

                                        // className="btn btn-primary w-100 fw-bold mt-3 rounded-pill shadow-sm"
                                        style={{ fontSize: "1.1rem", letterSpacing: "0.5px" }}
                                    >
                                        {object ? "💾 Update" : "💾 Save"}
                                    </button>
                                </div>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );


};

export default NewProductionCompoundChildPartForm;
