import React, { useState, useEffect } from "react";
import InputField from "../components/InputFields";
import myLogo from "../images/default2.png";
import { Link } from "react-router-dom";
import axios from "axios";
import { ArrowLeft } from "react-bootstrap-icons";
import { useLocation } from "react-router-dom";
import { useOutletContext } from "react-router-dom";
import LoadingSpinner from "../components/LoadingSpinner";
import { ClipboardList } from "lucide-react";
const BASE_URL = process.env.REACT_APP_BASE_URL;

const NewMachineForm = () => {
    const [loading, setLoading] = useState(true);
    const [machineId, setMachineId] = useState("");
    const [machineName, setMachineName] = useState("");
    const [description, setDescription] = useState("");
    const [barcode, setBarcode] = useState("");
    const [tonnage, setTonnage] = useState("")
    const [error, setError] = useState("");
    const { setAlert } = useOutletContext();
    const location = useLocation();
    const { object } = location.state || {};
    const [selectedImage, setSelectedImage] = useState(null); // real File
    const [previewUrl, setPreviewUrl] = useState(null);
    const [image, setImage] = useState(null);
    const [make, setMake] = useState("");
    const [dataRecord, setDataRecord] = useState("");
    const [ipAddress, setIpAddress] = useState("");
    const [port, setPort] = useState(""); 
    const [status, setStatus] = useState("");    // preview

    const handleImageChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            setSelectedImage(file); // 👈 real File object
            setPreviewUrl(URL.createObjectURL(file)); // 👈 preview blob URL
        } else {
            alert("Please Select a JPG and PNG image.");
        }
    };

    useEffect(() => {
        // // Runs on mount
        // loadCustomerListData();
        // loadUserListData();
        // loadPersonListData();
        // loadGroupListData();

        // Runs when object changes
        if (object) {
            setMachineId(object.machineId || "");
            setMachineName(object.machineName || "");
            setDescription(object.description || "");
            setTonnage(object.tonnage || "");
            setBarcode(object.barcode || "");
            setImage(object.image || "")
            setPreviewUrl(object.image || "");
            setMake(object.make || "");
            setDataRecord(object.dataRecord || "");
            setIpAddress(object.ipAddress || "");
            setPort(object.port || "");
            setStatus(object.status || "");
        }

        setLoading(false);
    }, [object]);

    const resetForm = async (e) => {
        setMachineId("");
        setMachineName("");
        setDescription("");
        setTonnage("");
        setBarcode("");
        setPreviewUrl("");
        setImage("");
        setMake("");
        setDataRecord("");
        setIpAddress("");
        setPort("");
        setStatus("");
        
    }

    const handleUploadAndSubmit = async (e) => {
        e.preventDefault();
        try {

            if (!selectedImage) {
                // alert("Please select an image first!");
                await handleSubmitForm(e);
                return;
            } else {

                const imageData = new FormData();
                imageData.append("image", selectedImage);

                const response = await axios.post(
                    BASE_URL + "/WebApplication/Controllers/uploadImage",
                    imageData,
                    { headers: { "Content-Type": "multipart/form-data" } }
                );
                alert("Image uploaded successfully!");

                // ✅ Directly pass the uploaded image name/path
                await handleSubmitForm(e, response.data);
                return;
            }

        } catch (error) {
            console.error("Error uploading:", error);
        }
    };


    const isBlankOrSpaces = (value = "") =>
        value.trim().length === 0;

    const handleSubmitForm = async (e, uploadedImage) => {
        e.preventDefault();

        if (isBlankOrSpaces(machineName) || isBlankOrSpaces(description)
            || isBlankOrSpaces(tonnage)) {
            alert("Please fill required column");
            return;
        }

        const data = {
            machineId: parseInt(machineId),
            machineName,
            description,
            barcode,
            tonnage,
            make,
            dataRecord,
            ipAddress,
            port,
            status,

            image: uploadedImage ? "/WebApplication/trainingResouces/" + uploadedImage + ".png" : image,   // ✅ use uploaded image instead of state
            dateTime: "",
            createdBy: "111",
        };

        try {
            const url = object
                ? BASE_URL + "/WebApplication/Controllers/editMachineMaster"
                : BASE_URL + "/WebApplication/Controllers/insertMachineMaster";

            const response = await axios.post(url, data, { withCredentials: true });

            setAlert({ type: "success", message: "Success : " + response.data });
            resetForm();
        } catch (err) {
            setAlert({ type: "danger", message: "Error : " + err.response?.data });
            console.error(err);
        }
    };

    return (
        <div className="card shadow-lg rounded-0 border-0 bg-light d-flex flex-column p-2"
            style={{
                width: "100%",
                minHeight: "100vh",
                background: "#f4f6f8",
            }}>
            {/* Header */}
            <div className="px-4 py-2 position-relative"
                style={{
                    background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                    color: "white"
                }}>
                {/* Title */}
                <h4 className="text-end fw-bold mb-0"><ClipboardList size={30} viewBox="0 1 24 24" className="me-2 text-white" />
                    {object ? "Update Machine" : "New Machine"}</h4>
                <div
                    className="position-absolute top-50 start-0 translate-middle-y ms-3"
                    style={{ zIndex: 10 }}
                >
                    <Link
                        to="/WebApplication/masterDashboard/machineMaster"
                        className="btn btn-light btn-sm d-flex align-items-center fw-semibold shadow-sm"
                    >
                        <ArrowLeft className="me-1" /><span className="d-none d-lg-inline">Back</span>
                    </Link>
                </div>
            </div>


            {error && <p className="text-danger text-center fw-semibold mt-2">{error}</p>}

            {loading ? (
                <LoadingSpinner message={`Loading .....`} />
            ) : (

                <div className="row g-1 p-1" style={{ maxHeight: "90vh", overflowY: "scroll" }}>

                    {/* Right Side - Illustration */}
                    <div className="col-md-4 bg-light rounded-3 shadow-sm">
                        <div className="d-flex justify-content-center align-items-center h-100">
                            <img
                                src={previewUrl || myLogo}  // 👈 replace with uploaded file if exists
                                alt="Project Illustration"
                                className="img-fluid"
                                style={{ maxWidth: "80%", opacity: 0.95 }}
                            />
                        </div>
                    </div>

                    {/* Left Side - Form */}
                    <div className="col-md-8" >
                        <form onSubmit={handleUploadAndSubmit} className="p-2 bg-light rounded-3 shadow-sm" style={{ height: "87vh", overflow: "auto" }}>
                            <div className="row g-1">
                                {/* Plant Name. */}
                                <div className="col-md-6 px-2">
                                    <InputField
                                        label="Machine Name"
                                        type="text"
                                        placeholder=""
                                        value={machineName}
                                        onChange={(e) => setMachineName(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* Image */}
                                <div className="col-md-6 px-2">
                                    <InputField
                                        label="Image"
                                        type="file"
                                        accept="image/png, image/jpeg"
                                        // value={customerAddress}
                                        onChange={handleImageChange}
                                    />
                                </div>


                                {/* Project Name */}
                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Description"
                                        type="text"
                                        placeholder=""
                                        value={description}
                                        onChange={(e) => setDescription(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* Project Name */}
                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Barcode"
                                        type="text"
                                        placeholder=""
                                        value={barcode}
                                        onChange={(e) => setBarcode(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* Project Manager */}
                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Tonnage"
                                        type="text"
                                        placeholder=""
                                        value={tonnage}
                                        onChange={(e) => setTonnage(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* Make */}
                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Make"
                                        type="text"
                                        value={make}
                                        onChange={(e) => setMake(e.target.value)}
                                    />
                                </div>

                                {/* Data Record */}
                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Data Record"
                                        type="text"
                                        value={dataRecord}
                                        onChange={(e) => setDataRecord(e.target.value)}
                                    />
                                </div>

                                {/* IP Address */}
                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="IP Address"
                                        type="text"
                                        value={ipAddress}
                                        onChange={(e) => setIpAddress(e.target.value)}
                                    />
                                </div>

                                {/* Port */}
                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Port"
                                        type="text"
                                        value={port}
                                        onChange={(e) => setPort(e.target.value)}
                                    />
                                </div>

                                <div className="col-md-4 px-2">
                                    <label className="form-label">Status</label>
                                    <select
                                        className="form-control"
                                        value={status}
                                        onChange={(e) => setStatus(e.target.value)}
                                    >
                                        <option value="">Select Status</option>
                                        <option value="RUNNING">Running</option>
                                        <option value="SHUTDOWN">Shutdown</option>
                                        <option value="MAINTENANCE">Maintenance</option>
                                    </select>
                                </div>

                                {/* Save Button */}
                                <div className="col-12 p-2 d-flex justify-content-start">
                                    <button
                                        type="submit"
                                        className="btn-woco btn btn-light btn-sm d-flex align-items-center fw-semibold shadow-sm"
                                        style={{ fontSize: "1.1rem", letterSpacing: "0.5px" }}
                                    >
                                        {object ? "💾 Update" : "💾 Save"}
                                    </button>
                                </div>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );


};

export default NewMachineForm;
