import React, { useState} from "react";
import { Outlet } from "react-router-dom";
import Sidebar from "../components/SideBar";
import DismissableAlert from "../components/DismissableAlert"; // import your alert
import StaticBackDropModal from "../components/StaticBackDropModal";
import { AnimatePresence, motion } from "framer-motion";
import { TrainingContext } from "./TrainingContext";
const BASE_URL = process.env.REACT_APP_BASE_URL;

function Dashboard() {
  const [alert, setAlert] = useState(null); // global alert state
  const [staticAlert, setStaticAlert] = useState(null);
  const [resourceList, setResourceList] = useState(null);
  const [trainingDetails, setTrainingDetails] = useState(null);
  const [uploadUrl, setUploadUrl] = useState("");
  const [reloadFunction, setReloadFunction] = useState(null);


  return (

    <div className="d-flex" style={{ height: "100vh", overflow: "hidden" }}>
      {/* Sidebar fixed on left */}
      <div>
        <Sidebar moduleName="Master Database" />
      </div>

      {/* Right content area - scrollable only */}
      <div className="flex-grow-1 p-2 pt-0" style={{ overflowY: "hidden", height: "100vh" }}>
        {/* 🔔 Global alert at top-right */}
        <DismissableAlert
          alert={alert}
          setDismissAlertNull={() => setAlert(null)}
        />

        <StaticBackDropModal
          alert={staticAlert}
          setDismissAlertNull={() => setStaticAlert(null)}
          resourceList={resourceList}
          uploadUrl={uploadUrl}
          reloadFunction={reloadFunction}
        />

        <TrainingContext.Provider
          value={{
            trainingDetails,
            setTrainingDetails,
            setUploadUrl,
            setReloadFunction
          }}
        >
          <AnimatePresence mode="wait">
            <motion.div
              initial={{ x: "100%", opacity: 0 }}
              animate={{ x: 0, opacity: 1 }}
              transition={{ duration: 0.8, ease: "easeInOut" }}
            >
              <Outlet
                context={{
                  setAlert,
                  setStaticAlert,
                  setResourceList,
                  setReloadFunction
                }}
              />
            </motion.div>
          </AnimatePresence>
        </TrainingContext.Provider>
      </div>
    </div>
  );

}

export default Dashboard;

