// CreateNewProject.js
import React, { useEffect, useState, useContext } from "react";
import axios from "axios";
import { useCallback } from "react";
import { Table, Button, } from "react-bootstrap";
import { useNavigate } from "react-router-dom";
import {
    Search,
    Plus,
    Download,
    Upload
} from "react-bootstrap-icons";
import { ClipboardList, } from "lucide-react";
import "bootstrap/dist/css/bootstrap.min.css";
import "../css/Table.css"
import SearchInputFields from "../components/SearchInputFields"
import Pager from "../components/Pager";
import { useOutletContext } from "react-router-dom";
import LoadingSpinner from "../components/LoadingSpinner";
import "../css/ModuleDashboard.css"
import "../css/preventive.css"
import { OverlayTrigger, Tooltip } from "react-bootstrap";
import { TrainingContext } from "./TrainingContext";
import { FaCalendarMinus, FaChargingStation, FaCircle, FaClock, FaEdit, FaTools, FaTrash } from "react-icons/fa";
const BASE_URL = process.env.REACT_APP_BASE_URL;

const PlantMaster = () => {
    const {
        setUploadUrl
    } = useContext(TrainingContext);
    const [loading, setLoading] = useState(true);
    const [tableData, setTableData] = useState([]);
    const [formData, setFormData] = useState({
        plantName: "",
        plantCode: "",
        plantDescription: "",
        packingCode: "",
        createdBy: "",
        dateTime: "",
        image: ""
    });
    const [currentPage, setCurrentPage] = useState(0);
    const [totalPages, setTotalPages] = useState(0);
    const [pageSize, setPageSize] = useState(10);// dynamic in real apps
    const sequenceNumber = pageSize * currentPage;
    // const { setAlert } = useOutletContext();
    const navigate = useNavigate();
    const { setAlert, setStaticAlert, setReloadFunction } = useOutletContext();
    const handleChange = (e) => {
        const { name, value } = e.target;
        const keys = name.split(".");

        setFormData(prev => {
            const updated = { ...prev };
            let current = updated;

            keys.forEach((key, index) => {
                if (index === keys.length - 1) {
                    current[key] = value;
                } else {
                    current[key] = { ...current[key] };
                    current = current[key];
                }
            });

            return updated;
        });
    };




    const loadTableData = useCallback(async () => {
        try {
            console.log(formData);
            setLoading(true);

            const response = await axios.post(
                BASE_URL + "/WebApplication/Controllers/getLikePreventiveMaintenance/" + currentPage + "/" + pageSize,
                formData,
                { withCredentials: true }
            );

            console.log("Data Load Successfully:", response);

            setTableData(response.data.content);
            setTotalPages(response.data.totalPages);
            setCurrentPage(response.data.pageable.pageNumber);

        } catch (error) {
            console.log(error);
        } finally {
            setLoading(false);
        }

    }, [formData, currentPage, pageSize]);

    useEffect(() => {
        if (setReloadFunction) {
            setReloadFunction(() => loadTableData);
        }
    }, [loadTableData]);

    // Handle form change
    const deleteData = async (id) => {
        try {
            const response = await axios.delete(
                `${BASE_URL}/WebApplication/Controllers/deletePlantMaster/${id}`,
                { withCredentials: true }
            );
            setAlert({ type: "success", message: "Success : " + response.data });
            loadTableData();
        } catch (error) {
            setAlert({ type: "danger", message: "Error : " + error.response.data });
            console.error(error);
            loadTableData();
        }
    };

    useEffect(() => {
        loadTableData();
    }, [currentPage, pageSize]); // empty deps → runs once

    const handleEnterKey = (e, callback) => {
        if (e.key === "Enter") {
            e.preventDefault();
            callback();
        }
    };

    const downloadTemplate = async () => {
        try {

            setLoading(true);

            const response = await axios.get(
                BASE_URL + "/WebApplication/Controllers/download/template/plantmaster",
                {
                    responseType: "blob", // ✅ VERY IMPORTANT
                    withCredentials: true,
                }
            );

            // Create blob link
            const url = window.URL.createObjectURL(new Blob([response.data]));

            const link = document.createElement("a");
            link.href = url;
            link.setAttribute("download", "Plant_Master_Template.xlsx");
            document.body.appendChild(link);
            link.click();

            // Cleanup
            link.remove();
            window.URL.revokeObjectURL(url);

            setLoading(false);

        } catch (error) {
            console.error("Download error:", error);

            setLoading(false);
        }
    };



    const downloadData = async () => {
        try {

            setLoading(true);

            const response = await axios.get(
                BASE_URL + "/WebApplication/Controllers/download/data/plantmaster",
                {
                    responseType: "blob", // ✅ VERY IMPORTANT
                    withCredentials: true,
                }
            );

            // Create blob link
            const url = window.URL.createObjectURL(new Blob([response.data]));

            const link = document.createElement("a");
            link.href = url;
            link.setAttribute("download", "Plant_Master.xlsx");
            document.body.appendChild(link);
            link.click();

            // Cleanup
            link.remove();
            window.URL.revokeObjectURL(url);

            setLoading(false);

        } catch (error) {
            console.error("Download error:", error);

            setLoading(false);
        }
    };

    // Resource mode
    const showUploadModal = async (resources) => {
        setStaticAlert({ type: "success", message: "Resource Download : " });
        setUploadUrl("uploadplant");
    };


    return (
        <div className="card shadow-lg rounded-0 border-0 bg-light d-flex flex-column p-2"
            style={{
                width: "100%",
                minHeight: "100vh",
                background: "#f4f6f8",
            }}>
            {/* Header */}
            <div className="px-4 py-2"
                style={{
                    background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                    color: "white"
                }}>
                {/* Title */}
                <h4 className="text-end fw-bold mb-0"><ClipboardList size={30} viewBox="0 1 24 24" className="me-2 text-white" />
                    Preventive Maintenance</h4>
            </div>

            <div className="row g-4 px-1">
                {/* Left Side - Form */}
                <div className="col-md-12">
                    <div className="d-flex my-1" style={{ height: "80vh" }}>
                        {/* LEFT SIDE TABLE */}
                        <div style={{ flex: 1, overflowY: "auto" }}>

                            {loading ? (
                                <LoadingSpinner message={`Loading .....`} />
                            ) : (
                                <div className="container-fluid p-0">
                                    <div className="container-fluid p-3 main-bg">
                                        {/* HEADER */}
                                        <div className="d-flex justify-content-between align-items-center mb-3">
                                            <h6 className="fw-semibold mb-0 title-text">Maintenance Plan</h6>

                                            <input
                                                type="text"
                                                className="form-control form-control-sm search-box"
                                                placeholder="Search..."
                                            // value={search}
                                            // onChange={(e) => setSearch(e.target.value)}
                                            />
                                        </div>

                                        {/* TABLE */}
                                        <div className="card table-card">
                                            <div className="table-responsive">
                                                <table className="table table-sm align-middle mb-0 custom-table">
                                                    <thead>
                                                        <tr>
                                                            <th>Mould Name</th>
                                                            <th>Child Part Name</th>
                                                            <th>Description</th>
                                                            <th>Total Life</th>
                                                            <th>Alarm Life</th>
                                                            <th>Current Life</th>
                                                            <th>PM Date</th>
                                                            <th>Alert Days</th>
                                                            <th>Days Remaining</th>
                                                            <th>Priority</th>
                                                            <th>Last</th>
                                                            <th>Next</th>
                                                        </tr>
                                                    </thead>

                                                    <tbody>
                                                        {tableData.map((item, i) => (
                                                            <tr key={i} className={`status-${item.priority?.toLowerCase()}`}>

                                                                <td className="fw-semibold">
                                                                    <FaTools className="me-2 icon-muted" size={12} />
                                                                    {item.mouldName}
                                                                </td>

                                                                <td className="small text-muted">
                                                                    {item.childPartName}
                                                                </td>

                                                                <td className="small text-muted">
                                                                    {item.description}
                                                                </td>

                                                                <td className="small text-muted">
                                                                    <FaClock className="me-1" size={12} />
                                                                    {item.totalLife}
                                                                </td>

                                                                <td className={`small text-muted status-${item.priority}`}>
                                                                    <FaCalendarMinus size={12} className="me-1" />
                                                                    {item.alarmLife}
                                                                </td>

                                                                <td className="small text-muted">
                                                                    {item.currentLife}
                                                                </td>
                                                                <td className="small text-muted">{item.pmDate}</td>
                                                                <td className="small text-muted">
                                                                    {item.alertDays}
                                                                </td>
                                                                <td className="small text-muted">{item.daysRemaining}</td>
                                                                <td className="small text-muted">{item.priority}</td>

                                                                <td className="small text-muted">{item.last}</td>
                                                                <td className="small text-muted">{item.next}</td>
                                                                <td className="text-center">
                                                                    <button className="btn btn-sm action-btn d-flex align-items-center gap-1">
                                                                        <FaTools size={12} />
                                                                        <span>Action</span>
                                                                    </button>
                                                                </td>

                                                            </tr>
                                                        ))}
                                                    </tbody>
                                                </table>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>

                        {/* RIGHT SIDE ACTION PANEL */}
                        {/* <div
                            style={{
                                width: "50px",
                                background: "linear-gradient(360deg, #0f6b5b, #0b4f43)",
                                color: "white",
                                borderLeft: "2px solid #e5e7eb",
                                display: "flex",
                                flexDirection: "column",
                                alignItems: "center",
                                paddingTop: "10px",
                                gap: "10px"
                            }}
                        >
                            <OverlayTrigger
                                placement="bottom"
                                overlay={<Tooltip id="download-tooltip">Add</Tooltip>}
                            >
                                <Button
                                    size="sm"
                                    className="btn btn-light shadow-sm"
                                    onClick={() =>
                                        navigate("/WebApplication/masterDashboard/plantMaster/addNewPlant", { state: { formData } })
                                    }
                                >
                                    <Plus size={20} />
                                </Button>
                            </OverlayTrigger>


                            <OverlayTrigger
                                placement="bottom"
                                overlay={<Tooltip id="download-tooltip">Download Template</Tooltip>}
                            >
                                <Button
                                    size="sm"
                                    className="btn btn-light shadow-sm"
                                    onClick={() => downloadTemplate()}
                                >
                                    <Download size={20} />
                                </Button>
                            </OverlayTrigger>


                            <OverlayTrigger
                                placement="bottom"
                                overlay={<Tooltip id="download-tooltip">Upload Template</Tooltip>}
                            >
                                <Button
                                    size="sm"
                                    className="btn btn-light shadow-sm"
                                    onClick={() => showUploadModal()}
                                >
                                    <Upload size={20} />
                                </Button>
                            </OverlayTrigger>


                            <OverlayTrigger
                                placement="bottom"
                                overlay={<Tooltip id="download-tooltip">Download Data</Tooltip>}
                            >
                                <Button
                                    size="sm"
                                    className="btn btn-light shadow-sm"
                                    onClick={() => downloadData()}
                                >
                                    <Download size={20} />
                                </Button>
                            </OverlayTrigger>

                        </div> */}

                    </div>
                </div>
            </div>


            <div className="row mt-2 mt-auto m-1"
                style={{
                    background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                    color: "white"
                }}>

                <div className="col-md-6 col-md-12 align-items-center radius-2">
                    <div className="m-2">
                        <Pager
                            currentPage={currentPage}
                            totalPages={totalPages}
                            onPageChange={setCurrentPage}
                            pageSize={pageSize}
                            onPageSizeChange={setPageSize}
                        />
                    </div>

                </div>
            </div>

        </div >
    );
};

export default PlantMaster;
